-- 시연용 실사풍 이미지(AI 생성)로 상품 대표·상세 이미지를 바꾼다. 원본: scripts/demo-products/photoreal_migration.py
-- 이미지는 docs/demo-products/photoreal/staging/*.webp. A=대표, B=상세 1번, C=상세 2번.
-- 큐레이션 33개는 상품명+장인 ID, 대표 56·상품별 이미지 158개는 상품명+소분류 ID 로 찾는다.
-- A·B·C 가 모두 있으면 2번 이후 상세를 지우고, A 만 있으면 상세를 지운다(일러스트가 섞이지 않게). 시드 상품(저장소 docs 이미지)만 바꾼다.

CREATE TEMP TABLE demo_photoreal_c (title VARCHAR(200), artisan_id BIGINT, main_url VARCHAR(500),
    detail0_url VARCHAR(500), detail1_url VARCHAR(500)) ON COMMIT DROP;

UPDATE product p SET thumbnail_url = r.main_url
FROM demo_photoreal_c r WHERE r.title = p.title AND r.artisan_id = p.artisan_id AND r.main_url IS NOT NULL AND p.thumbnail_url LIKE '%/Jangingmall/backend/%/docs/%';

SELECT p.product_id, 0, r.detail0_url FROM product p JOIN demo_photoreal_c r ON r.title = p.title AND r.artisan_id = p.artisan_id
WHERE r.detail0_url IS NOT NULL AND p.thumbnail_url LIKE '%/Jangingmall/backend/%/docs/%'
ON CONFLICT (product_id, display_order) DO UPDATE SET image_url = EXCLUDED.image_url;

SELECT p.product_id, 1, r.detail1_url FROM product p JOIN demo_photoreal_c r ON r.title = p.title AND r.artisan_id = p.artisan_id
WHERE r.detail1_url IS NOT NULL AND p.thumbnail_url LIKE '%/Jangingmall/backend/%/docs/%'
ON CONFLICT (product_id, display_order) DO UPDATE SET image_url = EXCLUDED.image_url;

DELETE FROM product_detail_image d USING product p JOIN demo_photoreal_c r ON r.title = p.title AND r.artisan_id = p.artisan_id
WHERE d.product_id = p.product_id AND p.thumbnail_url LIKE '%/Jangingmall/backend/%/docs/%'
  AND ((r.main_url IS NOT NULL AND r.detail0_url IS NOT NULL AND r.detail1_url IS NOT NULL AND d.display_order >= 2)
    OR (r.main_url IS NOT NULL AND r.detail0_url IS NULL AND r.detail1_url IS NULL));

CREATE TEMP TABLE demo_photoreal_s (title VARCHAR(200), subcategory_id BIGINT, main_url VARCHAR(500),
    detail0_url VARCHAR(500), detail1_url VARCHAR(500)) ON COMMIT DROP;

UPDATE product p SET thumbnail_url = r.main_url
FROM demo_photoreal_s r WHERE r.title = p.title AND r.subcategory_id = p.subcategory_id AND r.main_url IS NOT NULL AND p.thumbnail_url LIKE '%/Jangingmall/backend/%/docs/%';

SELECT p.product_id, 0, r.detail0_url FROM product p JOIN demo_photoreal_s r ON r.title = p.title AND r.subcategory_id = p.subcategory_id
WHERE r.detail0_url IS NOT NULL AND p.thumbnail_url LIKE '%/Jangingmall/backend/%/docs/%'
ON CONFLICT (product_id, display_order) DO UPDATE SET image_url = EXCLUDED.image_url;

SELECT p.product_id, 1, r.detail1_url FROM product p JOIN demo_photoreal_s r ON r.title = p.title AND r.subcategory_id = p.subcategory_id
WHERE r.detail1_url IS NOT NULL AND p.thumbnail_url LIKE '%/Jangingmall/backend/%/docs/%'
ON CONFLICT (product_id, display_order) DO UPDATE SET image_url = EXCLUDED.image_url;

DELETE FROM product_detail_image d USING product p JOIN demo_photoreal_s r ON r.title = p.title AND r.subcategory_id = p.subcategory_id
WHERE d.product_id = p.product_id AND p.thumbnail_url LIKE '%/Jangingmall/backend/%/docs/%'
  AND ((r.main_url IS NOT NULL AND r.detail0_url IS NOT NULL AND r.detail1_url IS NOT NULL AND d.display_order >= 2)
    OR (r.main_url IS NOT NULL AND r.detail0_url IS NULL AND r.detail1_url IS NULL));
